function memoize(fn, keyFn) {
  const cache = new Map();
  const toKey = keyFn || ((...args) => JSON.stringify(args));   // default key: stringify all args
  return function (...args) {
    const k = toKey(...args);
    if (cache.has(k)) return cache.get(k);                      // cache hit
    const v = fn(...args);                                      // miss: compute, store, return
    cache.set(k, v);
    return v;
  };
}

